import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.BvlN9b-o.js";const p=JSON.parse('{"title":"API 配置","description":"","frontmatter":{},"headers":[],"relativePath":"reference/config.md","filePath":"reference/config.md"}'),i={name:"reference/config.md"};function a(c,t,n,s,l,S){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="api-配置" tabindex="-1">API 配置 <a class="header-anchor" href="#api-配置" aria-label="Permalink to &quot;API 配置&quot;">​</a></h1><p>从 Settings 定义自动生成；生产秘密不进入文档。</p><table tabindex="0"><thead><tr><th>变量</th><th>默认值</th><th>敏感值</th><th>说明</th></tr></thead><tbody><tr><td><code>DATABASE_URL</code></td><td>必填</td><td>是</td><td>PostgreSQL connection URL. Required; never logged.</td></tr><tr><td><code>APP_BIND</code></td><td>127.0.0.1:3000</td><td>否</td><td>API listener IP address and port.</td></tr><tr><td><code>RUST_LOG</code></td><td>info</td><td>否</td><td>Structured log filter.</td></tr><tr><td><code>MIGRATION_TIMEOUT_SECS</code></td><td>30</td><td>否</td><td>Migration execution deadline in seconds (1..3600).</td></tr><tr><td><code>APP_ORIGIN</code></td><td><a href="http://127.0.0.1:5173" target="_blank" rel="noreferrer">http://127.0.0.1:5173</a></td><td>否</td><td>Trusted browser origin. HTTPS required except loopback development.</td></tr><tr><td><code>SESSION_ABSOLUTE_SECS</code></td><td>604800</td><td>否</td><td>Absolute session lifetime in seconds (60..2592000).</td></tr><tr><td><code>SESSION_IDLE_SECS</code></td><td>86400</td><td>否</td><td>Idle session lifetime in seconds (60..absolute lifetime).</td></tr><tr><td><code>S3_ENDPOINT</code></td><td>必填</td><td>否</td><td>Internal S3 endpoint at its root path. Unset disables object storage.</td></tr><tr><td><code>S3_PUBLIC_ENDPOINT</code></td><td>必填</td><td>否</td><td>Browser-accessible S3 origin. Defaults to S3_ENDPOINT; HTTPS except loopback.</td></tr><tr><td><code>S3_BUCKET</code></td><td>saas-files</td><td>否</td><td>Dedicated private application bucket.</td></tr><tr><td><code>S3_REGION</code></td><td>us-east-1</td><td>否</td><td>S3 signing region.</td></tr><tr><td><code>S3_ACCESS_KEY</code></td><td>必填</td><td>是</td><td>Explicit S3 access key; required when S3_ENDPOINT is set.</td></tr><tr><td><code>S3_SECRET_KEY</code></td><td>必填</td><td>是</td><td>Explicit S3 secret; required when enabled, never logged.</td></tr><tr><td><code>FILE_MAX_BYTES</code></td><td>20971520</td><td>否</td><td>File byte limit, verified again on the final object (1..104857600).</td></tr><tr><td><code>UPLOAD_SESSION_SECS</code></td><td>900</td><td>否</td><td>Upload resource/signing lifetime in seconds (1..3600).</td></tr><tr><td><code>DOWNLOAD_URL_SECS</code></td><td>60</td><td>否</td><td>Download capability lifetime in seconds (1..300). Revocation blocks new signing.</td></tr></tbody></table><p>开发脚本额外读取的 PostgreSQL 端口、Web 代理和教程 URL 见 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/98758401f22c89cab0ec7e411209815c7b105fae/.env.example" target="_blank" rel="noreferrer">.env.example</a>；它们不是浏览器可读取的 DATABASE_URL。</p>',4)])])}const f=d(i,[["render",a]]);export{p as __pageData,f as default};
